// Draw cool-toned spiral
function drawSpiral(x, y, len, angle, depth) {
    if (depth > 0) {
        // Calculate new position
        const newX = x + Math.cos(angle) * len;
        const newY = y + Math.sin(angle) * len;

        // Draw segment
        ctx.fillStyle = `hsl(${20 + (depth * 10)}, 70%, ${80 - (depth * 10)}%)`;
        ctx.fillRect(Math.round(newX), Math.round(newY), 2, 2);

        // Recursive calls for next segment
        drawSpiral(newX, newY, len * 0.8, angle + 0.3, depth - 1);
        drawSpiral(newX, newY, len * 0.8, angle - 0.3, depth - 1);
    }
}

