// Shell (spiral)
ctx.fillStyle = '#2F4F4F';
ctx.beginPath();
let r = 10;
for (let i = 0; i < 20; i++) {
    let angle = i * 0.5;
    let x = 200 + Math.cos(angle) * r;
    let y = 250 + Math.sin(angle) * r;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
    r += 3;
}
ctx.closePath();
ctx.fill();

// Shell details
ctx.fillStyle = '#000000';
for (let i = 0; i < 15; i++) {
    let angle = i * 0.7;
    let x = 200 + Math.cos(angle) * (r + 2);
    let y = 250 + Math.sin(angle) * (r + 2);
    ctx.fillRect(Math.round(x), Math.round(y), 1, 1);
}

